const CITY_SUGGESTIONS=['Москва','Санкт-Петербург','Невинномысск','Ставрополь','Краснодар','Ростов-на-Дону','Казань','Сочи','Екатеринбург','Новосибирск','Самара','Воронеж','Волгоград','Пермь','Уфа','Омск','Красноярск','Тюмень','Нижний Новгород'];
const REGION_SUGGESTIONS=['Ставропольский край','Краснодарский край','Москва','Московская область','Санкт-Петербург','Ленинградская область','Ростовская область','Республика Татарстан','Свердловская область','Новосибирская область'];
const scopeText=(v,max=90)=>typeof v==='string'?v.normalize('NFKC').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max):'';
const className=(number,letter)=>Number.isInteger(Number(number))&&Number(number)>=7&&Number(number)<=11&&/^[А-ЯЁ]{1,4}$/u.test(String(letter||'').toUpperCase())?String(number)+String(letter).toUpperCase():'';
function schoolIdentity(region,city,name){
 const r=scopeText(region,70),c=scopeText(city,70),n=scopeText(name,100);
 if(r.length<2||c.length<2||n.length<3)return null;
 const id=[r,c,n].map(v=>v.toLocaleLowerCase('ru-RU')).join('::');
 return {id,region:r,city:c,name:n};
}
const DEFAULT_SCHOOL=schoolIdentity('Ставропольский край','Невинномысск','Лицей №6');
function validatedSchool(input){
 if(!input||typeof input!=='object')return null;
 const school=schoolIdentity(input.region,input.city,input.name);
 return school&&input.id===school.id?school:null;
}
function spaceLabel(){return state.school?state.school.name:CFG.demoSpace;}
function spaceCityLabel(){return state.school?state.school.city:'Демонстрационная школа';}
function schoolStore(school){return SCHOOL_PREFIX+school.id;}
function joinSchool(values){
 const school=schoolIdentity(values.region,values.city,values.school);
 const grade=className(values.grade,scopeText(values.letter,4));
 if(!school){toast('Укажи регион, город и название школы');return false;}
 if(!grade){toast('Выбери класс с 7 по 11 и букву русского алфавита');return false;}
 let previous=null;
 try{const raw=localStorage.getItem(schoolStore(school));if(raw&&raw.length<700000)previous=JSON.parse(raw);}catch(e){console.warn('Данные школы не прочитаны',e)}
 state=previous?hydrate(previous):makeSeed();
 state.school=school;state.user.grade=grade;state.role=values.role==='organizer'?'organizer':'student';state.entered=true;
 state.section='home';state.search='';state.peopleSearch='';state.gradeFilter='ALL';state.letterFilter='ALL';modal=null;
 persist();scrollTopAfter=true;render();toast('Открыта демоверсия пространства школы');return true;
}

